head.script:
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('chkcombo').click()", "true");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('chkcombo_itemTable_0_checkbox').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('chkcombo_itemTable_2_checkbox').checked", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('chkcombo_itemTable_3_checkbox').checked", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('chkcombo_itemTable_4_checkbox').checked", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('chkcombo_itemTable_0_checkbox').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('chkcombo_itemTable_1_checkbox').checked", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('chkcombo_itemTable_2_checkbox').checked", "false");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('chkcombo_itemTable_3_checkbox').checked", "false");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('chkcombo_itemTable_4_checkbox').checked", "false");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();
scwin.onpageload = function() {
    chkcombo.setItemDisabled(1, true);
    chkcombo.setSelectedInfo([{
        index: 1,
        checked: true
    }]);
}
